$active_menu='assets';include 'header.php';require_once __DIR__.'/../foundation.php';$id=(int)($_GET['id']??0);oecrm_require_permission($conn,'assets',$id?'edit':'create');$companyId=oecrm_current_company_id($conn);$a=['id'=>0,'asset_code'=>'AST-'.date('ymd').'-','asset_type'=>'laptop','brand'=>'','model'=>'','serial_number'=>'','purchase_date'=>'','purchase_cost'=>'0','warranty_until'=>'','condition_status'=>'good','lifecycle_status'=>'available','notes'=>''];if($id){$a=mysqli_fetch_assoc(mysqli_query($conn,'SELECT * FROM assets WHERE id='.$id.' AND company_id='.$companyId));if(!$a){http_response_code(404);exit('Asset not found.');}}$employees=mysqli_query($conn,'SELECT id,employeeCode,name FROM employeestbl WHERE company_id='.$companyId.' AND status=0 ORDER BY name');$current=$id?mysqli_fetch_assoc(mysqli_query($conn,'SELECT al.*,e.name,e.employeeCode FROM asset_allocations al JOIN employeestbl e ON e.id=al.employee_id WHERE al.asset_id='.$id.' AND al.status="allocated" LIMIT 1')):null;$history=$id?mysqli_query($conn,'SELECT h.*,e.name employee_name FROM asset_history h LEFT JOIN employeestbl e ON e.id=h.employee_id WHERE h.asset_id='.$id.' ORDER BY h.id DESC'):null;$error=$_SESSION['asset_error']??'';unset($_SESSION['asset_error']);
?><div id="page-wrapper" class="compact-admin-page resource-form-page"><div class="foundation-titlebar"><a href="assets.php"><i class="fa fa-arrow-left"></i> Assets</a><h2><?php echo $id?'Asset Details':'New Asset';?></h2></div><?php if($error):?><div class="alert alert-danger"><?php echo oecrm_h($error);?></div><?php endif;?><div class="asset-layout"><section><div class="panel panel-default"><div class="panel-heading">Asset Profile</div><div class="panel-body"><form method="post" action="assetAction.php" class="resource-form"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo $id;?>"><div class="form-group"><label>Asset Code</label><input class="form-control" name="asset_code" value="<?php echo oecrm_h($a['asset_code']);?>" required></div><div class="form-group"><label>Type</label><select class="form-control" name="asset_type"><?php foreach(['laptop','desktop','monitor','mouse','keyboard','headphones','mobile','other'] as $v):?><option value="<?php echo $v;?>" <?php echo $a['asset_type']===$v?'selected':'';?>><?php echo ucfirst($v);?></option><?php endforeach;?></select></div><div class="form-group"><label>Brand</label><input class="form-control" name="brand" value="<?php echo oecrm_h($a['brand']);?>"></div><div class="form-group"><label>Model</label><input class="form-control" name="model" value="<?php echo oecrm_h($a['model']);?>"></div><div class="form-group"><label>Serial Number</label><input class="form-control" name="serial_number" value="<?php echo oecrm_h($a['serial_number']);?>"></div><div class="form-group"><label>Purchase Date</label><input class="form-control" type="date" name="purchase_date" value="<?php echo oecrm_h($a['purchase_date']);?>"></div><div class="form-group"><label>Purchase Cost</label><input class="form-control" type="number" step=".01" min="0" name="purchase_cost" value="<?php echo oecrm_h($a['purchase_cost']);?>"></div><div class="form-group"><label>Warranty Until</label><input class="form-control" type="date" name="warranty_until" value="<?php echo oecrm_h($a['warranty_until']);?>"></div><div class="form-group"><label>Condition</label><select class="form-control" name="condition_status"><?php foreach(['new','good','fair','damaged'] as $v):?><option value="<?php echo $v;?>" <?php echo $a['condition_status']===$v?'selected':'';?>><?php echo ucfirst($v);?></option><?php endforeach;?></select></div><div class="form-group"><label>Lifecycle Status</label><select class="form-control" name="lifecycle_status"><?php foreach(['available','repair','retired','lost'] as $v):?><option value="<?php echo $v;?>" <?php echo $a['lifecycle_status']===$v?'selected':'';?>><?php echo ucfirst($v);?></option><?php endforeach;?></select></div><div class="form-group resource-notes"><label>Notes</label><textarea class="form-control" name="notes"><?php echo oecrm_h($a['notes']);?></textarea></div><div class="resource-actions"><button class="btn btn-primary"><i class="fa fa-save"></i> Save Asset</button></div></form></div></div></section><aside><?php if($id):?><div class="panel panel-default"><div class="panel-heading"><?php echo $current?'Current Allocation':'Allocate Asset';?></div><div class="panel-body"><?php if($current):?><p><strong><?php echo oecrm_h($current['name']);?></strong><br><?php echo oecrm_h($current['employeeCode']);?><br>Since <?php echo date('d M Y',strtotime($current['allocated_on']));?></p><form method="post" action="assetAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="return"><input type="hidden" name="id" value="<?php echo $id;?>"><select class="form-control" name="return_condition"><?php foreach(['good','fair','damaged'] as $v):?><option value="<?php echo $v;?>"><?php echo ucfirst($v);?></option><?php endforeach;?></select><br><button class="btn btn-warning btn-block"><i class="fa fa-undo"></i> Return Asset</button></form><?php else:?><form method="post" action="assetAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="allocate"><input type="hidden" name="id" value="<?php echo $id;?>"><select class="form-control" name="employee_id" required><option value="">Select employee</option><?php while($e=mysqli_fetch_assoc($employees)):?><option value="<?php echo $e['id'];?>"><?php echo oecrm_h($e['employeeCode'].' - '.$e['name']);?></option><?php endwhile;?></select><br><input class="form-control" type="date" name="allocated_on" value="<?php echo date('Y-m-d');?>" required><br><button class="btn btn-success btn-block"><i class="fa fa-user-plus"></i> Allocate</button></form><?php endif;?></div></div><div class="panel panel-default"><div class="panel-heading">Asset History</div><div class="panel-body project-side-list"><?php while($h=mysqli_fetch_assoc($history)):?><div><i class="fa fa-history"></i><span><strong><?php echo ucfirst($h['event_type']);?></strong><small><?php echo oecrm_h(($h['employee_name']?$h['employee_name'].' | ':'').date('d M Y H:i',strtotime($h['created_at'])));?></small></span></div><?php endwhile;?></div></div><?php endif;?></aside></div></div><?php include 'footer.php';?>
